(1540855, 204559, 30214, '<td valign="top">stunning shot!</td>', 'stunning shot!', '2005-07-17 11:54:59.000000', NULL, 1),
(1540856, 204855, 24454, '<td valign="top">Ohmygoodness!   This is an awesome photo!!!   Such a wonderful sky to compliment your picture.   I wonder if you hiked all the way up there?   Or if there was a road.  VERY impressive if it was a hike.</td>', 'Ohmygoodness!   This is an awesome photo!!!   Such a wonderful sky to compliment your picture.   I wonder if you hiked all the way up there?   Or if there was a road.  VERY impressive if it was a hike.', '2005-07-17 11:55:40.000000', NULL, 1),
(1540858, 204813, 30214, '<td valign="top">I love the idea, but I am not sure I like the blue tint. Still, 6.</td>', 'I love the idea, but I am not sure I like the blue tint. Still, 6.', '2005-07-17 11:56:16.000000', NULL, 1),
(1540860, 203362, 24454, '<td valign="top">I love the depth of field in this.   That background just makes this look awesome.   And I don''t even like bug pictures. . . .but I like this one.</td>', 'I love the depth of field in this.   That background just makes this look awesome.   And I don''t even like bug pictures. . . .but I like this one.', '2005-07-17 11:56:31.000000', NULL, 1),
