(1542774, 204868, 33352, '<td valign="top">Well taken, the different wave angles improve the composition...8</td>', 'Well taken, the different wave angles improve the composition...8', '2005-07-18 02:47:25.000000', NULL, 1),
(1542776, 203969, 37409, '<td valign="top">Too much PS for my taste.<br/>If I look at it from a Pop Art angle it''s cool.</td>', 'Too much PS for my taste.If I look at it from a Pop Art angle it''s cool.', '2005-07-18 02:47:52.000000', NULL, 1),
