INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1544774, 204527, 27605, '<td valign="top">One of the best shots I''ve seen of flying aircraft (and not just in this challenge... but ever!)  (7)</td>', 'One of the best shots I''ve seen of flying aircraft (and not just in this challenge... but ever!)  (7)', '2005-07-18 21:08:40.000000', NULL, 1),
(1544775, 203814, 8377, '<td valign="top">This is a beautiful shot! The girl really stands out against the water, and I love her outstretched arms. This photo really draws me in too. 10   :)</td>', 'This is a beautiful shot! The girl really stands out against the water, and I love her outstretched arms. This photo really draws me in too. 10   :)', '2005-07-18 21:08:55.000000', NULL, 1),
(1544778, 202575, 27605, '<td valign="top">Yeah he sure looks like that flag, doesn''t he?  Great shot.  (7)</td>', 'Yeah he sure looks like that flag, doesn''t he?  Great shot.  (7)', '2005-07-18 21:09:54.000000', NULL, 1),
(1544779, 204862, 8377, '<td valign="top">The colors in this are stunning!!! Very captivating photo as well. Such a beautiful shot, and the perfect amount of sharpness. 10</td>', 'The colors in this are stunning!!! Very captivating photo as well. Such a beautiful shot, and the perfect amount of sharpness. 10', '2005-07-18 21:09:57.000000', NULL, 1),
(1544782, 203336, 27605, '<td valign="top">Wow, he reminds me of Jay Leno!</td>', 'Wow, he reminds me of Jay Leno!', '2005-07-18 21:10:46.000000', NULL, 1),
(1544783, 202751, 33672, '<td valign="top">I like the perspective, Comp and grasp of theme. Soft focus doesn''t work for me here but the idea still scores well . If your model was in the shadow instead of the sun it may have been come out crisper. Easier to set the autofocus or meter the light.</td>', 'I like the perspective, Comp and grasp of theme. Soft focus doesn''t work for me here but the idea still scores well . If your model was in the shadow instead of the sun it may have been come out crisper. Easier to set the autofocus or meter the light.', '2005-07-18 21:10:56.000000', NULL, 1),
(1544786, 204845, 8377, '<td valign="top">This is so neat! I love how you followed the girl so that she would remain in focus while the bkg is not. This is a great idea, one of my favs in this challenge!  I bet this does really well.</td>', 'This is so neat! I love how you followed the girl so that she would remain in focus while the bkg is not. This is a great idea, one of my favs in this challenge!  I bet this does really well.', '2005-07-18 21:11:04.000000', NULL, 1),
(1544787, 202730, 27605, '<td valign="top">Had to think about this one a lo-o-o-o-ong time :o)  (7)</td>', 'Had to think about this one a lo-o-o-o-ong time :o)  (7)', '2005-07-18 21:11:27.000000', NULL, 1),
(1544789, 202394, 8377, '<td valign="top">Very neat idea for independence. I love your twist on the typical flag shot.</td>', 'Very neat idea for independence. I love your twist on the typical flag shot.', '2005-07-18 21:11:38.000000', NULL, 1),
(1544793, 204001, 8377, '<td valign="top">Very cool, excellent silohuette. Perfect time of day to take this shot. Great idea for the challenge!</td>', 'Very cool, excellent silohuette. Perfect time of day to take this shot. Great idea for the challenge!', '2005-07-18 21:12:27.000000', NULL, 1),
(1544794, 204787, 33672, '<td valign="top">The dark horizon takes away from a great Idea. I like how you used the minimalism approach here. Very theme oriented!</td>', 'The dark horizon takes away from a great Idea. I like how you used the minimalism approach here. Very theme oriented!', '2005-07-18 21:12:42.000000', NULL, 1),
(1544796, 202394, 33672, '<td valign="top">This is such a great Idea, a deeper DOF that would produce a crisper image would have put this onto the winners podium!</td>', 'This is such a great Idea, a deeper DOF that would produce a crisper image would have put this onto the winners podium!', '2005-07-18 21:13:50.000000', NULL, 1),
(1544802, 202768, 33672, '<td valign="top">A tighter crop may have served you better. Great idea but there''s too much going on and it takes a while for me to figure out who''s the subject.</td>', 'A tighter crop may have served you better. Great idea but there''s too much going on and it takes a while for me to figure out who''s the subject.', '2005-07-18 21:15:54.000000', NULL, 1),
(1544805, 204814, 27605, '<td valign="top">Oh wow, beautiful!  I like the b/w, seems very appropriate with the strong geometrical elements and wonderfully dramatic lighting.  The light is awesome, especially her hand being lit and her face peering back into the darkness she''s ''escaping''.  All parents have seen this look as the toddler scoots for freedom, very universal.  Absolutely a 10, and my pick for blue so far.</td>', 'Oh wow, beautiful!  I like the b/w, seems very appropriate with the strong geometrical elements and wonderfully dramatic lighting.  The light is awesome, especially her hand being lit and her face peering back into the darkness she''s ''escaping''.  All parents have seen this look as the toddler scoots for freedom, very universal.  Absolutely a 10, and my pick for blue so far.', '2005-07-18 21:17:26.000000', NULL, 1),
(1544812, 204762, 36299, '<td valign="top">Great capture.</td>', 'Great capture.', '2005-07-18 21:19:54.000000', NULL, 1),
(1544813, 204832, 27605, '<td valign="top">Awesome macro, I am sure I''m not the only one to wonder if you didn''t accidentally enter this in the wrong category.  Either way, a fabulous shot!</td>', 'Awesome macro, I am sure I''m not the only one to wonder if you didn''t accidentally enter this in the wrong category.  Either way, a fabulous shot!', '2005-07-18 21:20:21.000000', NULL, 1),
(1544815, 204524, 36299, '<td valign="top">Very cute.  I like the shallow DOF.</td>', 'Very cute.  I like the shallow DOF.', '2005-07-18 21:20:50.000000', NULL, 1),
