(1544892, 203149, 2780, '<td valign="top">This does nothing for me. Not enough contrast, not sharp, light glare on the surface (could fix with a polarizer), no real subject, not much connection to the challenge, just overall not appealing to me. 1</td>', 'This does nothing for me. Not enough contrast, not sharp, light glare on the surface (could fix with a polarizer), no real subject, not much connection to the challenge, just overall not appealing to me. 1', '2005-07-18 21:53:17.000000', NULL, 1),
(1544894, 202165, 2780, '<td valign="top">Excellent contrast and a great photo. The grain and dust spots add a lot. I''m glad you weren''t allowed to clone them out. 9</td>', 'Excellent contrast and a great photo. The grain and dust spots add a lot. I''m glad you weren''t allowed to clone them out. 9', '2005-07-18 21:53:59.000000', NULL, 1),
(1544896, 204432, 2780, '<td valign="top">Its a shame the sky is so bright, maybe you could have cropped in closer, but otherwise I really like this show. The B&amp;W and silhouetting works great. 9</td>', 'Its a shame the sky is so bright, maybe you could have cropped in closer, but otherwise I really like this show. The B&W and silhouetting works great. 9', '2005-07-18 21:54:05.000000', NULL, 1),
