(1544898, 204024, 2780, '<td valign="top">This is a great shot. The B&amp;W and the composition and the sharpness are spot on. The only problem is the blown out sky but with the dark rocks below and the basic editing rules, you definately made the best out of a tough situation. 9</td>', 'This is a great shot. The B&W and the composition and the sharpness are spot on. The only problem is the blown out sky but with the dark rocks below and the basic editing rules, you definately made the best out of a tough situation. 9', '2005-07-18 21:54:16.000000', NULL, 1),
(1544900, 203653, 2780, '<td valign="top">Really nice shot with great contrast and stuff, but the chain over the face spoils it I think. 8</td>', 'Really nice shot with great contrast and stuff, but the chain over the face spoils it I think. 8', '2005-07-18 21:54:28.000000', NULL, 1),
