(1545797, 204858, 36616, '<td valign="top">Ribbon material - love it</td>', 'Ribbon material - love it', '2005-07-19 08:51:38.000000', NULL, 1),
(1545806, 203167, 36616, '<td valign="top">Expecting at least a top ten for this. Only possible criticism is the colour of the background may be too intense although I have no idea what may be better.</td>', 'Expecting at least a top ten for this. Only possible criticism is the colour of the background may be too intense although I have no idea what may be better.', '2005-07-19 08:54:26.000000', NULL, 1),
(1545817, 204527, 36616, '<td valign="top">Great capture - love the trails. Could be independent in many ways including the right to not release smoke. Not serious comment - not independent due to being together - looking for at least top ten here.</td>', 'Great capture - love the trails. Could be independent in many ways including the right to not release smoke. Not serious comment - not independent due to being together - looking for at least top ten here.', '2005-07-19 08:57:17.000000', NULL, 1),
(1545820, 204845, 36616, '<td valign="top">Great sense of enjoyment from this pic. Well captured, good colours. hope the movement blur doesn''t cause too many lower votes - 8</td>', 'Great sense of enjoyment from this pic. Well captured, good colours. hope the movement blur doesn''t cause too many lower votes - 8', '2005-07-19 08:58:47.000000', NULL, 1),
(1545822, 203151, 36616, '<td valign="top">Love the expression here. Would have preferred not to have cropped top of head if possible</td>', 'Love the expression here. Would have preferred not to have cropped top of head if possible', '2005-07-19 09:00:10.000000', NULL, 1),
(1545828, 204164, 36616, '<td valign="top">Great effect but distracted by the light join line under the chin - such a shame - 7</td>', 'Great effect but distracted by the light join line under the chin - such a shame - 7', '2005-07-19 09:03:29.000000', NULL, 1),
(1545835, 204776, 36616, '<td valign="top">Like the colours and the message. Dislike the heaviness of the frame on this shot - would have preferred a lighter one if it is necessary at all.<br/>May be a stupid observation but I would have preferred to see the footprints going away from the camera. Yes I know that would have ben difficult. Expecting a top ten at least here.</td>', 'Like the colours and the message. Dislike the heaviness of the frame on this shot - would have preferred a lighter one if it is necessary at all.May be a stupid observation but I would have preferred to see the footprints going away from the camera. Yes I know that would have ben difficult. Expecting a top ten at least here.', '2005-07-19 09:08:30.000000', NULL, 1),
(1545838, 204488, 36616, '<td valign="top">Good emotion. Question the word again in the title - would have worked with still for me - maybe that is a personal  POV. expecting a good high finish for this stylish shot - well done.</td>', 'Good emotion. Question the word again in the title - would have worked with still for me - maybe that is a personal  POV. expecting a good high finish for this stylish shot - well done.', '2005-07-19 09:10:53.000000', NULL, 1),
