INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1550549, 203884, 40386, '<td valign="top">I would have liked to see a bit more contrast in this photo, looks a bit washed out, great shot</td>', 'I would have liked to see a bit more contrast in this photo, looks a bit washed out, great shot', '2005-07-20 15:03:37.000000', NULL, 1),
(1550587, 203362, 40860, '<td valign="top">i am doing many pics similar to this, lots of dragonfly neer my house, and i find catching them when they fly is SO hard, anyways, you could have taken a faster picture, but it is really nice</td>', 'i am doing many pics similar to this, lots of dragonfly neer my house, and i find catching them when they fly is SO hard, anyways, you could have taken a faster picture, but it is really nice', '2005-07-20 15:14:49.000000', NULL, 1),
