(1556102, 203478, 3214, '<td valign="top">Well done expression of the theme, with no identifying corporate marks it''s easy to regard this guy as an independent operator, driving secondary roads to avoid getting weighed, etc.</td>', 'Well done expression of the theme, with no identifying corporate marks it''s easy to regard this guy as an independent operator, driving secondary roads to avoid getting weighed, etc.', '2005-07-22 22:25:13.000000', NULL, 1),
(1556103, 204814, 3214, '<td valign="top">Independent little two year old, eh?  Your photo gives the impression that she is totally alone, without supervision, making a successful getaway.  I like how she''s leaving the frame, too.</td>', 'Independent little two year old, eh?  Your photo gives the impression that she is totally alone, without supervision, making a successful getaway.  I like how she''s leaving the frame, too.', '2005-07-22 22:26:16.000000', NULL, 1),
(1556107, 204635, 3214, '<td valign="top">Excellent anthropomorphism!  I feel as helpless as that green guy, but making my statement nonetheless.  I like the DOF you chose, as well as the height from which you shot.</td>', 'Excellent anthropomorphism!  I feel as helpless as that green guy, but making my statement nonetheless.  I like the DOF you chose, as well as the height from which you shot.', '2005-07-22 22:27:09.000000', NULL, 1),
(1556110, 204676, 3214, '<td valign="top">A beautiful solitary pursuit, the alone-ness adds to the realization of the theme.  Beautiful tones and sharpness at the back of the jetski/wake.</td>', 'A beautiful solitary pursuit, the alone-ness adds to the realization of the theme.  Beautiful tones and sharpness at the back of the jetski/wake.', '2005-07-22 22:28:16.000000', NULL, 1),
(1556183, 204676, 30881, '<td valign="top">Great light and shadow and really like the choppy strip just above subjects head. This is definitely a "10" Excellent!!</td>', 'Great light and shadow and really like the choppy strip just above subjects head. This is definitely a "10" Excellent!!', '2005-07-22 23:27:20.000000', NULL, 1),
