(1572666, 204763, 41066, '<td valign="top">Nice Shot.  I like how deep the tones of green in the background is. Clarity is great on the flower.</td>', 'Nice Shot.  I like how deep the tones of green in the background is. Clarity is great on the flower.', '2005-07-29 21:33:59.000000', NULL, 0),
(1572692, 202753, 41066, '<td valign="top">This is a great picture.  I love the sharpness of the key, which is the object of independence in this pic.  I love the angle.  Well Done!</td>', 'This is a great picture.  I love the sharpness of the key, which is the object of independence in this pic.  I love the angle.  Well Done!', '2005-07-29 22:03:37.000000', NULL, 0),
